33	  node app.ts group history --id <id>
34	                                    查看分组成员版本历史(只读)
35	  node app.ts group daily --id <id> --from <iso> --to <iso>
36	                                    按当时生效成员的分组能耗日报(只读)
37	  node app.ts correct --request <id> --item --device <设备> --at <iso> --expect <kWh> --set <kWh>
38	                                    [--item --device ... --at ... --expect ... --set ...]...
39	                                    批量修正已存读数的累计值(整批成功或整批拒绝)
40	  node app.ts undo --request <id> --target <修正请求标识>
