168	interface ParsedOptions {
169	  devices: string[];
170	  from?: number;
171	  to?: number;
172	}
173	
174	/** 解析 --device/--from/--to 选项;出错返回错误消息字符串。 */
175	function parseOptions(rest: string[]): ParsedOptions | string {
176	  const devices: string[] = [];
177	  let from: number | undefined;
178	  let to: number | undefined;
179	  for (let i = 0; i < rest.length; i++) {
180	    let opt = rest[i];
181	    let value: string | undefined;
182	    const eq = opt.indexOf('=');
183	    if (opt.startsWith('--') && eq !== -1) {
184	      value = opt.slice(eq + 1);
185	      opt = opt.slice(0, eq);
186	    } else if (opt.startsWith('--')) {
187	      value = rest[i + 1];
188	      if (value === undefined) return `选项 '${opt}' 缺少值`;
189	      i++;
190	    } else {
191	      return `无法识别的参数 '${opt}'`;
192	    }
193	    if (opt === '--device') {
194	      if (value.trim() === '') return "'--device' 的值不能为空";
195	      devices.push(value);
196	    } else if (opt === '--from' || opt === '--to') {
197	      const ts = parseIso8601(value.trim());
198	      if (ts === null) {
199	        return `选项 '${opt}' 的时间无效: '${value}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`;
200	      }
201	      if (opt === '--from') from = ts;
202	      else to = ts;
203	    } else {
204	      return `无法识别的选项 '${opt}'`;
205	    }
206	  }
207	  return { devices, from, to };
208	}
209	
210	/** 解析 --opt value / --opt=value 形式的选项;出错返回错误消息字符串。 */
211	function parseFlags(rest: string[], allowed: string[]): Map<string, string[]> | string {
212	  const out = new Map<string, string[]>();
213	  for (let i = 0; i < rest.length; i++) {
214	    let opt = rest[i];
215	    let value: string | undefined;
216	    const eq = opt.indexOf('=');
217	    if (opt.startsWith('--') && eq !== -1) {
218	      value = opt.slice(eq + 1);
219	      opt = opt.slice(0, eq);
220	    } else if (opt.startsWith('--')) {
221	      value = rest[i + 1];
222	      if (value === undefined) return `选项 '${opt}' 缺少值`;
223	      i++;
224	    } else {
225	      return `无法识别的参数 '${opt}'`;
226	    }
227	    if (!allowed.includes(opt)) return `无法识别的选项 '${opt}'`;
228	    const list = out.get(opt);
229	    if (list) list.push(value);
230	    else out.set(opt, [value]);
231	  }
232	  return out;
233	}
234	
235	/** 取恰好出现一次的单值选项;缺失或重复返回 null。 */
236	function oneFlag(flags: Map<string, string[]>, name: string): string | null {
237	  const list = flags.get(name);
238	  if (!list || list.length !== 1) return null;
239	  return list[0];
240	}
241	
242	/** 解析 YYYY-MM-DD 日期选项;无效时返回错误消息字符串。 */
243	function dateFlag(value: string, label: string): number | string {
244	  const ts = parseUtcDate(value.trim());
245	  if (ts === null) return `${label}无效: '${value.trim()}'(需 YYYY-MM-DD 的真实 UTC 日期)`;
246	  return ts;
247	}
248	
249	function cmdRule(rest: string[]): number {
250	  const [sub, ...subrest] = rest;
251	  if (sub === 'list') {
252	    if (subrest.length !== 0) return usageError("'rule list' 不接受参数");
253	    return cmdRuleList();
254	  }
255	  if (sub === 'create') {
256	    const flags = parseFlags(subrest, ['--id', '--device', '--group', '--threshold']);
257	    if (typeof flags === 'string') return usageError(flags);
258	    const idRaw = oneFlag(flags, '--id');
259	    const deviceList = flags.get('--device');
260	    const groupList = flags.get('--group');
261	    const thresholdRaw = oneFlag(flags, '--threshold');
262	    if (idRaw === null || thresholdRaw === null) {
263	      return usageError("'rule create' 需要 --id 与 --threshold 各恰好一个");
264	    }
265	    const hasDevice = deviceList !== undefined;
266	    const hasGroup = groupList !== undefined;
267	    if (hasDevice === hasGroup) {
268	      return usageError("'rule create' 需恰好提供 --device <设备> 或 --group <分组> 之一");
269	    }
270	    if ((deviceList !== undefined && deviceList.length !== 1) ||
271	      (groupList !== undefined && groupList.length !== 1)) {
272	      return usageError("'rule create' 的目标选项只能出现一次");
273	    }
274	    const id = idRaw.trim();
275	    if (id === '') return usageError('规则标识不能为空');
276	    const thresholdMilli = parseKwh(thresholdRaw.trim());
277	    if (thresholdMilli === null) {
278	      return usageError(`阈值无效: '${thresholdRaw.trim()}'(需非负、最多三位小数的 kWh)`);
279	    }
280	    if (hasDevice) {
281	      const device = (deviceList as string[])[0].trim();
282	      if (device === '') return usageError("'--device' 的值不能为空");
283	      return cmdRuleCreate({ id, targetType: 'device', targetId: device, thresholdMilli });
284	    }
285	    const group = (groupList as string[])[0].trim();
286	    if (group === '') return usageError("'--group' 的值不能为空");
287	    return cmdRuleCreate({ id, targetType: 'group', targetId: group, thresholdMilli });
288	  }
289	  if (sub === undefined) return usageError("'rule' 需要子命令 create 或 list");
290	  return usageError(`无法识别的 rule 子命令 '${sub}'`);
291	}
292	
293	function cmdEvaluateEntry(rest: string[]): number {
294	  const flags = parseFlags(rest, ['--rule', '--from', '--to']);
295	  if (typeof flags === 'string') return usageError(flags);
296	  const ruleRaw = oneFlag(flags, '--rule');
297	  const fromRaw = oneFlag(flags, '--from');
298	  const toRaw = oneFlag(flags, '--to');
299	  if (ruleRaw === null || fromRaw === null || toRaw === null) {
300	    return usageError("'evaluate' 需要 --rule、--from、--to 各恰好一个(日期为 YYYY-MM-DD,起日含、止日不含)");
301	  }
302	  const ruleId = ruleRaw.trim();
303	  if (ruleId === '') return usageError('规则标识不能为空');
304	  const from = dateFlag(fromRaw, '起始日期');
305	  if (typeof from === 'string') return usageError(from);
306	  const to = dateFlag(toRaw, '结束日期');
307	  if (typeof to === 'string') return usageError(to);
308	  if (from >= to) return usageError('评估起日必须早于止日(--from < --to)');
309	  return cmdEvaluate({ ruleId, from, to });
310	}
311	
312	function cmdAlertsEntry(rest: string[]): number {
313	  const flags = parseFlags(rest, ['--rule', '--from', '--to']);
314	  if (typeof flags === 'string') return usageError(flags);
315	  const ruleRaw = oneFlag(flags, '--rule');
316	  if (ruleRaw === null) return usageError("'alerts' 需要 --rule 恰好一个");
317	  const ruleId = ruleRaw.trim();
318	  if (ruleId === '') return usageError('规则标识不能为空');
319	  const fromList = flags.get('--from');
320	  const toList = flags.get('--to');
321	  if ((fromList !== undefined) !== (toList !== undefined)) {
322	    return usageError("'alerts' 的 --from 与 --to 需同时提供或同时省略");
323	  }
324	  let from: number | undefined;
325	  let to: number | undefined;
326	  if (fromList !== undefined) {
327	    const fromRaw = oneFlag(flags, '--from');
328	    const toRaw = oneFlag(flags, '--to');
329	    if (fromRaw === null || toRaw === null) {
330	      return usageError("'alerts' 的 --from 与 --to 各只能出现一次");
331	    }
332	    const fromParsed = dateFlag(fromRaw, '起始日期');
333	    if (typeof fromParsed === 'string') return usageError(fromParsed);
334	    const toParsed = dateFlag(toRaw, '结束日期');
335	    if (typeof toParsed === 'string') return usageError(toParsed);
336	    if (fromParsed >= toParsed) return usageError('查询起日必须早于止日(--from < --to)');
337	    from = fromParsed;
338	    to = toParsed;
339	  }
340	  return cmdAlerts({ ruleId, from, to });
341	}
342	
343	function cmdGroup(rest: string[]): number {
344	  const [sub, ...subrest] = rest;
345	  if (sub === 'configure') {
346	    const flags = parseFlags(subrest, ['--id', '--at', '--device']);
347	    if (typeof flags === 'string') return usageError(flags);
348	    const idRaw = oneFlag(flags, '--id');
349	    const atRaw = oneFlag(flags, '--at');
350	    const deviceList = flags.get('--device') ?? [];
351	    if (idRaw === null || atRaw === null) {
352	      return usageError("'group configure' 需要 --id 与 --at 各恰好一个");
353	    }
354	    if (deviceList.length === 0) {
355	      return usageError("'group configure' 需要至少一个 --device(成员不能为空)");
356	    }
357	    const id = idRaw.trim();
358	    if (id === '') return usageError('分组标识不能为空');
359	    const at = parseIso8601(atRaw.trim());
360	    if (at === null) {
361	      return usageError(
362	        `选项 '--at' 的时间无效: '${atRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`,
363	      );
364	    }
365	    const members: string[] = [];
366	    for (const d of deviceList) {
367	      const m = d.trim();
368	      if (m === '') return usageError("'--device' 的值不能为空");
369	      members.push(m);
370	    }
371	    return cmdGroupConfigure({ id, at, members });
372	  }
373	  if (sub === 'history') {
374	    const flags = parseFlags(subrest, ['--id']);
375	    if (typeof flags === 'string') return usageError(flags);
376	    const idRaw = oneFlag(flags, '--id');
377	    if (idRaw === null) return usageError("'group history' 需要 --id 恰好一个");
378	    const id = idRaw.trim();
379	    if (id === '') return usageError('分组标识不能为空');
380	    return cmdGroupHistory({ id });
381	  }
382	  if (sub === 'daily') {
383	    const flags = parseFlags(subrest, ['--id', '--from', '--to']);
384	    if (typeof flags === 'string') return usageError(flags);
385	    const idRaw = oneFlag(flags, '--id');
386	    const fromRaw = oneFlag(flags, '--from');
387	    const toRaw = oneFlag(flags, '--to');
388	    if (idRaw === null || fromRaw === null || toRaw === null) {
389	      return usageError("'group daily' 需要 --id、--from、--to 各恰好一个(起点含、终点不含)");
390	    }
391	    const id = idRaw.trim();
392	    if (id === '') return usageError('分组标识不能为空');
393	    const from = parseIso8601(fromRaw.trim());
394	    if (from === null) {
395	      return usageError(`选项 '--from' 的时间无效: '${fromRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`);
396	    }
397	    const to = parseIso8601(toRaw.trim());
398	    if (to === null) {
399	      return usageError(`选项 '--to' 的时间无效: '${toRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`);
400	    }
401	    if (from >= to) return usageError('查询起点必须早于终点(--from < --to)');
402	    return cmdGroupDaily({ id, from, to });
403	  }
404	  if (sub === undefined) return usageError("'group' 需要子命令 configure、history 或 daily");
405	  return usageError(`无法识别的 group 子命令 '${sub}'`);
406	}
407	
408	/**
409	 * 解析 correct 的修正项:以裸 '--item' 分段,每段需 --device/--at/--expect/--set
410	 * 各恰好一个。出错返回错误消息字符串。
411	 */
412	function parseCorrectItems(rest: string[]): { requestId: string; items: CorrectionItem[] } | string {
413	  const segments: string[][] = [[]];
414	  for (const tok of rest) {
415	    if (tok === '--item') segments.push([]);
416	    else segments[segments.length - 1].push(tok);
417	  }
418	  const headFlags = parseFlags(segments[0], ['--request']);
419	  if (typeof headFlags === 'string') return headFlags;
420	  const requestRaw = oneFlag(headFlags, '--request');
421	  if (requestRaw === null) return "'correct' 需要 --request 恰好一个";
422	  const requestId = requestRaw.trim();
423	  if (requestId === '') return '请求标识不能为空';
424	  const itemSegs = segments.slice(1);
425	  if (itemSegs.length === 0) {
426	    return "'correct' 需要至少一个 --item(--item --device <设备> --at <iso> --expect <kWh> --set <kWh>)";
427	  }
428	  const items: CorrectionItem[] = [];
429	  for (const seg of itemSegs) {
430	    const flags = parseFlags(seg, ['--device', '--at', '--expect', '--set']);
431	    if (typeof flags === 'string') return flags;
432	    const deviceRaw = oneFlag(flags, '--device');
433	    const atRaw = oneFlag(flags, '--at');
434	    const expectRaw = oneFlag(flags, '--expect');
435	    const setRaw = oneFlag(flags, '--set');
436	    if (deviceRaw === null || atRaw === null || expectRaw === null || setRaw === null) {
437	      return '每个 --item 需要 --device、--at、--expect、--set 各恰好一个';
438	    }
439	    const device = deviceRaw.trim();
440	    if (device === '') return "'--device' 的值不能为空";
441	    const ts = parseIso8601(atRaw.trim());
442	    if (ts === null) {
443	      return `选项 '--at' 的时间无效: '${atRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`;
444	    }
445	    const expectedMilli = parseKwh(expectRaw.trim());
446	    if (expectedMilli === null) {
447	      return `预期原读数无效: '${expectRaw.trim()}'(需非负、最多三位小数的 kWh)`;
448	    }
449	    const replacementMilli = parseKwh(setRaw.trim());
450	    if (replacementMilli === null) {
451	      return `替换读数无效: '${setRaw.trim()}'(需非负、最多三位小数的 kWh)`;
452	    }
453	    items.push({ device, ts, expectedMilli, replacementMilli });
454	  }
455	  return { requestId, items };
456	}
457	
458	function cmdCorrectEntry(rest: string[]): number {
459	  const parsed = parseCorrectItems(rest);
460	  if (typeof parsed === 'string') return usageError(parsed);
461	  return cmdCorrect(parsed.requestId, parsed.items);
462	}
463	
464	function cmdUndoEntry(rest: string[]): number {
465	  const flags = parseFlags(rest, ['--request', '--target']);
466	  if (typeof flags === 'string') return usageError(flags);
467	  const requestRaw = oneFlag(flags, '--request');
468	  const targetRaw = oneFlag(flags, '--target');
469	  if (requestRaw === null || targetRaw === null) {
470	    return usageError("'undo' 需要 --request 与 --target 各恰好一个");
471	  }
472	  const requestId = requestRaw.trim();
473	  if (requestId === '') return usageError('撤销请求标识不能为空');
474	  const targetId = targetRaw.trim();
475	  if (targetId === '') return usageError('目标修正请求标识不能为空');
476	  return cmdUndo(requestId, targetId);
477	}
478	
479	function main(args: string[]): number {
480	  if (args.length === 0) {
481	    console.log(help);
482	    return 0;
483	  }
484	  const [cmd, ...rest] = args;
485	  if (rest.length === 0 && (cmd === '--help' || cmd === '-h')) {
486	    console.log(help);
487	    return 0;
488	  }
489	
490	  if (cmd === 'import') {
491	    if (rest.length !== 1) return usageError("'import' 需要且仅需要一个 CSV 文件路径");
492	    return cmdImport(rest[0]);
493	  }
494	
495	  if (cmd === 'readings') {
496	    const parsed = parseOptions(rest);
497	    if (typeof parsed === 'string') return usageError(parsed);
498	    if (parsed.from !== undefined && parsed.to !== undefined && parsed.from >= parsed.to) {
499	      return usageError('查询起点必须早于终点(--from < --to)');
500	    }
501	    return cmdReadings(parsed);
502	  }
503	
504	  if (cmd === 'daily') {
505	    const parsed = parseOptions(rest);
506	    if (typeof parsed === 'string') return usageError(parsed);
507	    if (parsed.from === undefined || parsed.to === undefined) {
508	      return usageError("'daily' 必须同时提供 --from 与 --to(起点含、终点不含)");
509	    }
510	    if (parsed.from >= parsed.to) {
511	      return usageError('查询起点必须早于终点(--from < --to)');
512	    }
513	    return cmdDaily({ devices: parsed.devices, from: parsed.from, to: parsed.to });
514	  }
515	
516	  if (cmd === 'rule') return cmdRule(rest);
517	  if (cmd === 'evaluate') return cmdEvaluateEntry(rest);
518	  if (cmd === 'alerts') return cmdAlertsEntry(rest);
519	  if (cmd === 'group') return cmdGroup(rest);
520	  if (cmd === 'correct') return cmdCorrectEntry(rest);
521	  if (cmd === 'undo') return cmdUndoEntry(rest);
522	
523	  if (cmd === 'corrections') {
524	    if (rest.length !== 0) return usageError("'corrections' 不接受参数");
525	    return cmdCorrections();
526	  }
527	
528	  if (cmd === 'ack') {
529	    if (rest.length !== 1) return usageError("'ack' 需要且仅需要一个告警标识");
530	    const alertId = rest[0].trim();
531	    if (alertId === '') return usageError('告警标识不能为空');
532	    return cmdAck(alertId);
533	  }
534	
535	  return usageError(`无法识别的参数 '${cmd}'`);
536	}
537	
538	process.exitCode = main(process.argv.slice(2));
