// 命名时区分日:用运行环境自带的 Intl(ECMA-402)解析 IANA 时区,
// 按当地墙钟把查询范围切成自然日。不按固定 86400 秒或全年固定偏移
// 推算日界线:夏令时前拨跳过的当天更短(跳过的小时不存在,不补为未知),
// 回拨当天更长(重复小时按各自实际时刻完整计入);同一当地日期在不连续
// 时段出现时合并统计、时段分别保留;整日被跳过的当地日期没有实际时段,
// 不生成虚构日报。

export interface LocalDayPeriod {
  /** 时段起点(含),epoch 秒。 */
  start: number;
  /** 时段终点(不含),epoch 秒。 */
  end: number;
}

export interface LocalDay {
  /** 当地日期标签,YYYY-MM-DD。 */
  label: string;
  /** 该当地日期在查询范围内的实际 UTC 时段,按时间升序、互不重叠。 */
  periods: LocalDayPeriod[];
}

interface WallClock {
  /** 日期比较键,y*10000+m*100+d。 */
  key: number;
  /** 日期标签,YYYY-MM-DD。 */
  label: string;
  /** 墙钟分量按 UTC 解释的 epoch 秒(用于偏移与午夜推算)。 */
  naive: number;
  /** 下一个当地午夜的墙钟,按 UTC 解释的 epoch 秒。 */
  nextMidnight: number;
}

/** 校验 IANA 时区名并构造墙钟格式化器;运行环境不支持时返回 null。 */
export function loadTimezone(name: string): Intl.DateTimeFormat | null {
  if (name === '') return null;
  try {
    const fmt = new Intl.DateTimeFormat('en-US', {
      timeZone: name,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      hourCycle: 'h23',
    });
    fmt.format(0);
    return fmt;
  } catch {
    return null;
  }
}

/** 年月日时分秒按 UTC 解释的 epoch 秒(setUTCFullYear 以支持 0-99 年)。 */
function naiveEpoch(y: number, mo: number, d: number, h: number, mi: number, s: number): number {
  const dt = new Date(0);
  dt.setUTCFullYear(y, mo - 1, d);
  dt.setUTCHours(h, mi, s, 0);
  return dt.getTime() / 1000;
}

/** 时刻 t 在时区 fmt 下的墙钟。 */
function wallClock(fmt: Intl.DateTimeFormat, t: number): WallClock {
  let y = 0;
  let mo = 0;
  let d = 0;
  let h = 0;
  let mi = 0;
  let s = 0;
  for (const p of fmt.formatToParts(t * 1000)) {
    switch (p.type) {
      case 'year':
        y = Number(p.value);
        break;
      case 'month':
        mo = Number(p.value);
        break;
      case 'day':
        d = Number(p.value);
        break;
      case 'hour':
        h = Number(p.value);
        break;
      case 'minute':
        mi = Number(p.value);
        break;
      case 'second':
        s = Number(p.value);
        break;
    }
  }
  const pad = (n: number): string => String(n).padStart(2, '0');
  return {
    key: y * 10000 + mo * 100 + d,
    label: `${String(y).padStart(4, '0')}-${pad(mo)}-${pad(d)}`,
    naive: naiveEpoch(y, mo, d, h, mi, s),
    nextMidnight: naiveEpoch(y, mo, d, 0, 0, 0) + 86400,
  };
}

/** 时区在时刻 t 的偏移(墙钟 - UTC),秒。 */
function offsetAt(fmt: Intl.DateTimeFormat, t: number): number {
  return wallClock(fmt, t).naive - t;
}

/**
 * 在 (t, limit] 内找第一个偏移与 o0 不同的时刻;没有返回 Infinity。
 * 先按小时步进定位再秒级二分;IANA 时区的相邻偏移切换间隔远大于一小时,
 * 一小时内两次切换且净偏移不变的情形不存在。
 */
function nextTransition(fmt: Intl.DateTimeFormat, t: number, o0: number, limit: number): number {
  let lo = t;
  let u = t;
  while (u < limit) {
    u = Math.min(u + 3600, limit);
    if (offsetAt(fmt, u) !== o0) {
      let hi = u;
      while (hi - lo > 1) {
        const mid = (lo + hi) >> 1;
        if (offsetAt(fmt, mid) !== o0) hi = mid;
        else lo = mid;
      }
      return hi;
    }
    lo = u;
  }
  return Infinity;
}

/**
 * 把 [from, to) 按当地自然日切分。返回按首次出现排序(即日期升序)的
 * 当地日期,每个日期带实际统计的 UTC 时段;同一日期的不连续时段合并到
 * 同一日期下分别列出,相邻时段并为一个区间。没有实际时段的当地日期
 * (如整体被跳过的日期)不出现。
 */
export function localDays(fmt: Intl.DateTimeFormat, from: number, to: number): LocalDay[] {
  const days: LocalDay[] = [];
  const byKey = new Map<number, LocalDay>();
  let cursor = from;
  while (cursor < to) {
    const w = wallClock(fmt, cursor);
    const o0 = w.naive - cursor;
    // 偏移不变时下一次日期变化的 UTC 时刻;wall(cursor) < nextMidnight,
    // 故 uStar > cursor 恒成立。
    const uStar = w.nextMidnight - o0;
    // 偏移切换可能先于午夜到达(如午夜前后切换夏令时),此时日期是否变化
    // 由下一轮以新偏移重新计算;段内偏移恒定,日期不会中途改变。
    const trans = nextTransition(fmt, cursor, o0, Math.min(uStar, to));
    const end = Math.min(uStar, trans, to);
    let day = byKey.get(w.key);
    if (!day) {
      day = { label: w.label, periods: [] };
      byKey.set(w.key, day);
      days.push(day);
    }
    const last = day.periods[day.periods.length - 1];
    if (last && last.end === cursor) last.end = end;
    else day.periods.push({ start: cursor, end });
    cursor = end;
  }
  return days;
}

// daily 子命令:按当地自然日核查能耗的只读日报,默认 UTC,可用 --tz 指定
// 运行环境支持的 IANA 时区。时区只决定分日,不重新解释输入时刻或已存读数。
//
// 估算口径:
// - 区间由每个设备完整已存时序的相邻读数构成,两端读数即使在查询范围外
//   也参与;范围内没有读数但被区间覆盖时仍得到结果。
// - 非下降区间把累计值之差按持续时间均匀分摊:以千分之一 kWh 为单位,
//   从区间起点累计到任一切点 t 的比例量为 floor(diff*(t-start)/duration),
//   片段消耗为终点与起点累计量之差。切点为查询边界与当地日界线,因此
//   完整区间的分摊总量等于原差值,同一区间拆开查询再相加结果一致;
//   新的日界线不重置分摊起点。
// - 中间乘积与多区间汇总使用 BigInt,超过 Number 安全整数范围仍精确。
// - 下降区间不分摊消耗,记为异常覆盖;其后的区间仍从下降后的读数计算。
// - 首条读数之前、末条之后及孤立读数时段为未知,不外推。
// - 日界线按实际时刻的当地日期归属计算,不用固定 86400 秒或固定偏移推算:
//   夏令时前拨当天更短(跳过的小时不补为未知),回拨当天更长(重复小时按
//   各自实际时刻完整计入);同一当地日期的不连续时段合并统计、分别列出;
//   没有实际时段的当地日期不生成日报。

import { loadStore, StoreError, dataFilePath, type Reading } from './store.ts';
import { formatIsoUtc } from './time.ts';
import { localDays, loadTimezone, type LocalDay } from './tz.ts';
import { formatKwh } from './value.ts';

export interface DailyFilter {
  devices: string[];
  /** 查询起点(含),epoch 秒。 */
  from: number;
  /** 查询终点(不含),epoch 秒。 */
  to: number;
  /** 分日时区(IANA 名称);省略时按 UTC。 */
  tz?: string;
}

export const DAY_SECONDS = 86400;

function err(message: string): void {
  console.error(`meterwatch: ${message}`);
}

export interface DayStats {
  /** 有效(非下降区间)覆盖秒数。 */
  valid: number;
  /** 异常(下降区间)覆盖秒数。 */
  anomaly: number;
  /** 未知(无区间覆盖)秒数。 */
  unknown: number;
  /** 该天分摊消耗,毫千瓦时;仅 valid > 0 时有意义。 */
  consumption: bigint;
}

/** 计算 [segStart, segEnd) 一天的统计;区间取自完整时序。 */
export function computeDay(series: Reading[], segStart: number, segEnd: number): DayStats {
  let valid = 0;
  let anomaly = 0;
  let consumption = 0n;
  for (let i = 1; i < series.length; i++) {
    const a = series[i - 1];
    const b = series[i];
    const lo = Math.max(a.ts, segStart);
    const hi = Math.min(b.ts, segEnd);
    if (lo >= hi) continue;
    const diff = b.milli - a.milli;
    if (diff < 0n) {
      anomaly += hi - lo;
    } else {
      valid += hi - lo;
      const duration = BigInt(b.ts - a.ts);
      const total = diff;
      // 从区间起点累计到 t 的比例量(向下取整);BigInt 除法向零截断,
      // 被除数非负,等价于向下取整。
      const cumulative = (t: number): bigint => (total * BigInt(t - a.ts)) / duration;
      consumption += cumulative(hi) - cumulative(lo);
    }
  }
  const unknown = segEnd - segStart - valid - anomaly;
  return { valid, anomaly, unknown, consumption };
}

/** 汇总一天内各 UTC 时段的统计;三类秒数之和等于这些时段的总秒数。 */
export function sumDayStats(series: Reading[], day: LocalDay): DayStats {
  let valid = 0;
  let anomaly = 0;
  let unknown = 0;
  let consumption = 0n;
  for (const p of day.periods) {
    const s = computeDay(series, p.start, p.end);
    valid += s.valid;
    anomaly += s.anomaly;
    unknown += s.unknown;
    consumption += s.consumption;
  }
  return { valid, anomaly, unknown, consumption };
}

/**
 * 输出按当地自然日划分的能耗日报。只读,不修改数据。
 * 同设备同一实际时刻存在多条存储记录时报错并返回 1。
 * 返回进程退出码。
 */
export function cmdDaily(filter: DailyFilter): number {
  const tzName = filter.tz ?? 'UTC';
  const tz = loadTimezone(tzName);
  if (!tz) {
    err(`unknown timezone '${tzName}' (expect an IANA timezone name supported by this runtime)`);
    return 2;
  }
  const days = localDays(tz, filter.from, filter.to);

  const storePath = dataFilePath();
  let all: Reading[];
  try {
    all = loadStore(storePath);
  } catch (e) {
    if (e instanceof StoreError) {
      err(e.message);
      return 1;
    }
    throw e;
  }

  const byDevice = new Map<string, Reading[]>();
  for (const r of all) {
    const list = byDevice.get(r.device);
    if (list) list.push(r);
    else byDevice.set(r.device, [r]);
  }
  for (const [device, list] of byDevice) {
    list.sort((a, b) => a.ts - b.ts);
    for (let i = 1; i < list.length; i++) {
      if (list[i].ts === list[i - 1].ts) {
        err(
          `storage error: multiple stored readings for device '${device}' at ${formatIsoUtc(list[i].ts)}`,
        );
        return 1;
      }
    }
  }

  const wanted =
    filter.devices.length > 0 ? [...new Set(filter.devices)] : [...byDevice.keys()];
  wanted.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));

  console.log(`timezone: ${tzName}`);
  let printed = false;
  for (const device of wanted) {
    const series = byDevice.get(device);
    if (!series) continue;
    printed = true;

    console.log(`device: ${device}`);
    let total = 0n;
    let computedDays = 0;
    let incomplete = false;
    for (const day of days) {
      const stats = sumDayStats(series, day);
      const dayIncomplete = stats.anomaly > 0 || stats.unknown > 0;
      if (dayIncomplete) incomplete = true;

      let consumption: string;
      if (stats.valid > 0) {
        consumption = `consumption=${formatKwh(stats.consumption)} kWh (estimate)`;
        total += stats.consumption;
        computedDays++;
      } else {
        consumption = 'consumption=n/a (no valid coverage)';
      }
      let line =
        `  ${day.label}  ${consumption}` +
        `  valid=${stats.valid}s  anomaly=${stats.anomaly}s  unknown=${stats.unknown}s`;
      if (dayIncomplete) line += '  INCOMPLETE';
      console.log(line);
      for (const p of day.periods) {
        console.log(`    period=${formatIsoUtc(p.start)}..${formatIsoUtc(p.end)}`);
      }
    }

    const totalText =
      computedDays > 0
        ? `total consumption=${formatKwh(total)} kWh (estimate)`
        : 'total consumption=n/a (no valid coverage)';
    const status = incomplete
      ? 'status=INCOMPLETE (unknown or anomaly coverage present)'
      : 'status=complete';
    console.log(
      `  summary: device=${device}  computed=${computedDays}/${days.length} day(s)  ${totalText}  ${status}`,
    );
  }
  if (!printed) console.log('no matching devices');
  return 0;
}
